def vocabulary():
    result=[]
    for topic,(common,text) in GROUPS.items():
        for entry in text.strip().split('|'):
            name, clues=entry.strip().split(':')
            for typo,correct in [('llev ar','llevar'),('b bolsillo','bolsillo'),('b ola','bola'),('m esa','mesa'),('tr ébol','trébol')]: clues=clues.replace(typo,correct)
            result.append({'prompt':name,'forbidden':clues.split(',')+common.split(','),'topic':topic,'difficulty':'easy' if topic in ('animales','hogar','gastronomía') else 'medium'})
    return result
